package com.greenocean.backend.listener.planning;
import com.greenocean.backend.listener.live.*;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.time.*;import java.util.*;import static com.greenocean.backend.listener.planning.ListenerSupportPolicy.*;
@Service @Transactional(noRollbackFor=LiveSupportException.class)
public class ListenerSessions {
 private final ListenerSupportPolicy p;private final LiveSupportService live;private final ListenerCalendar calendar;private final ListenerDataPolicy data;
 public ListenerSessions(ListenerSupportPolicy p,LiveSupportService live,ListenerCalendar calendar,ListenerDataPolicy data){this.p=p;this.live=live;this.calendar=calendar;this.data=data;}
 public record Proposal(@NotNull UUID clientKey){}
 public record Feedback(Boolean helpful,Boolean respected,Boolean wouldRequestAgain,@Min(0)long revision){}
 private Map<String,Object> owned(UUID id,UUID who){var rows=p.db.queryForList("SELECT * FROM live_support_requests WHERE id=? AND(member_id=? OR listener_id=?)",id,who,who);if(rows.isEmpty())throw denied(404,"SESSION_NOT_FOUND","Support session was not found.");return rows.getFirst();}
 private Map<String,Object> extension(UUID id){var rows=p.db.queryForList("SELECT id,requester_id,client_key,status,reason_code,seconds,original_deadline,expires_at,member_approved_at,listener_approved_at,applied_at FROM listener_session_extensions WHERE session_id=?",id);return rows.isEmpty()?Map.of():rows.getFirst();}
 private boolean feedbackWindow(Map<String,Object> r){Integer days=data.days().get("FEEDBACK");return days!=null&&r.get("ended_at")!=null&&p.now().isBefore(instant(r.get("ended_at")).plus(Duration.ofDays(days)));}
 public Map<String,Object> plan(UUID id,UUID who){p.liveLock();live.reconcile();p.eligible(who);var r=owned(id,who);var ex=extension(id);var safe=new LinkedHashMap<>(ex);safe.remove("requester_id");safe.remove("client_key");if(!ex.isEmpty())safe.put("requestedByMember",r.get("member_id").equals(ex.get("requester_id")));
  var out=new LinkedHashMap<String,Object>();out.put("serverTime",p.now());out.put("limits",p.limits());out.put("extension",safe);out.put("extensionEnabled",p.extension());out.put("extensionAvailable",p.extension()&&ex.isEmpty()&&p.truth("SELECT listener_session_extendible(?)",id));out.put("followupEnabled",p.followup());out.put("feedbackAllowed",p.followup()&&who.equals(r.get("member_id"))&&"COMPLETED".equals(r.get("status"))&&r.get("planned_seconds")!=null&&feedbackWindow(r));out.put("privateNotesEnabled",false);return out;
 }
 public Map<String,Object> request(UUID id,UUID who,Proposal in){p.liveLock();live.reconcile();p.require("EXTENSION");p.eligible(who);var r=owned(id,who);p.lock((UUID)r.get("member_id"),(UUID)r.get("listener_id"));var existing=extension(id);if(!existing.isEmpty()){if(who.equals(existing.get("requester_id"))&&in.clientKey().equals(existing.get("client_key")))return plan(id,who);throw denied(409,"EXTENSION_ALREADY_PROPOSED","Review the existing extension proposal; each session permits one proposal and at most one extension.");}p.bound(who,"EXTENSION_REQUEST",10);if(!p.truth("SELECT listener_session_extendible(?)",id))throw denied(409,"EXTENSION_UNAVAILABLE","Extra time is unavailable for the current session or its next commitments. The original deadline remains.");p.db.update("INSERT INTO listener_session_extensions(session_id,requester_id,client_key,original_deadline,expires_at) VALUES(?,?,?,listener_support_now(),listener_support_now())",id,who,in.clientKey());boolean notices=p.truth("SELECT COALESCE((SELECT reminders FROM listener_bookings WHERE id=?),(SELECT reminders FROM listener_wait_queue WHERE id=?),FALSE)",r.get("source_booking_id"),r.get("source_queue_id"));p.notice(who.equals(r.get("member_id"))?(UUID)r.get("listener_id"):(UUID)r.get("member_id"),(UUID)extension(id).get("id"),"EXTENSION_REQUESTED",notices);return plan(id,who);}
 private Map<String,Object> proposal(UUID session,UUID proposal){var e=extension(session);if(e.isEmpty()||!proposal.equals(e.get("id")))throw denied(404,"EXTENSION_NOT_FOUND","This extension proposal was not found for the session.");return e;}
 public Map<String,Object> decide(UUID session,UUID id,UUID who,boolean approve){p.liveLock();live.reconcile();p.require("EXTENSION");p.eligible(who);var r=owned(session,who);p.lock((UUID)r.get("member_id"),(UUID)r.get("listener_id"));var e=proposal(session,id);if("APPLIED".equals(e.get("status")))return plan(session,who);if(!"PENDING".equals(e.get("status")))throw denied(409,"EXTENSION_CLOSED","This extension proposal is no longer open. The session cannot be revived.");if(!"ACTIVE".equals(r.get("status")))throw denied(409,"SESSION_NOT_ACTIVE","Extension cannot resume or reopen a session.");if(!approve){p.db.update("UPDATE listener_session_extensions SET status='DECLINED',reason_code='PARTICIPANT_DECLINED' WHERE id=?",id);return plan(session,who);}
  if(!p.truth("SELECT listener_session_extendible(?)",session)){p.db.update("UPDATE listener_session_extensions SET status='UNAVAILABLE',reason_code='CAPACITY_OR_AUTHORIZATION_CHANGED' WHERE id=?",id);throw denied(409,"EXTENSION_UNAVAILABLE","Current authorization or commitments prevent extra time. The original session deadline remains.");}
  String column=who.equals(r.get("member_id"))?"member_approved_at":"listener_approved_at";p.db.update("UPDATE listener_session_extensions SET "+column+"=COALESCE("+column+",listener_support_now()) WHERE id=?",id);
  p.db.update("UPDATE listener_session_extensions SET status='APPLIED',applied_at=listener_support_now() WHERE id=? AND status='PENDING' AND member_approved_at IS NOT NULL AND listener_approved_at IS NOT NULL",id);return plan(session,who);
 }
 private Map<String,Object> completed(UUID session,UUID who){p.eligible(who);var r=owned(session,who);if(!who.equals(r.get("member_id")))throw denied(403,"FEEDBACK_OWNER_REQUIRED","Only the member can access their optional feedback.");if(!"COMPLETED".equals(r.get("status"))||r.get("planned_seconds")==null)throw denied(409,"FEEDBACK_NOT_AVAILABLE","Optional feedback is available after a completed N session.");return r;}
 public Map<String,Object> feedback(UUID session,UUID who){live.reconcile();completed(session,who);var rows=p.db.queryForList("SELECT helpful,respected,would_request_again,revision,created_at,updated_at FROM listener_session_feedback WHERE session_id=? AND owner_id=?",session,who);return rows.isEmpty()?Map.of():rows.getFirst();}
 public Map<String,Object> saveFeedback(UUID session,UUID who,Feedback in){p.liveLock();live.reconcile();p.require("FOLLOWUP");var record=completed(session,who);if(!feedbackWindow(record))throw denied(409,"FEEDBACK_WINDOW_ENDED","The optional feedback window ended under the approved retention policy.");p.bound(who,"FEEDBACK",30);if(in.helpful()==null&&in.respected()==null&&in.wouldRequestAgain()==null)throw new IllegalArgumentException("Choose at least one optional answer, or skip feedback without saving");var current=feedback(session,who);if(!current.isEmpty()&&Objects.equals(in.helpful(),current.get("helpful"))&&Objects.equals(in.respected(),current.get("respected"))&&Objects.equals(in.wouldRequestAgain(),current.get("would_request_again")))return current;
  if(current.isEmpty()){if(in.revision()!=0)throw denied(409,"FEEDBACK_CHANGED","Reload your optional feedback before changing it.");p.db.update("INSERT INTO listener_session_feedback(session_id,owner_id,helpful,respected,would_request_again) VALUES(?,?,?,?,?)",session,who,in.helpful(),in.respected(),in.wouldRequestAgain());}
  else if(p.db.update("UPDATE listener_session_feedback SET helpful=?,respected=?,would_request_again=?,revision=revision+1,updated_at=listener_support_now() WHERE session_id=? AND owner_id=? AND revision=?",in.helpful(),in.respected(),in.wouldRequestAgain(),session,who,in.revision())!=1)throw denied(409,"FEEDBACK_CHANGED","Reload your optional feedback before changing it.");return feedback(session,who);
 }
 public void removeFeedback(UUID session,UUID who){p.liveLock();owned(session,who);if(p.db.queryForObject("SELECT member_id FROM live_support_requests WHERE id=?",UUID.class,session).equals(who))p.db.update("DELETE FROM listener_session_feedback WHERE session_id=? AND owner_id=?",session,who);else throw denied(403,"FEEDBACK_OWNER_REQUIRED","Only the member can remove their optional feedback.");}
 public ListenerCalendar.Slots repeat(UUID session,UUID who){p.require("FOLLOWUP");live.reconcile();var r=completed(session,who);p.listener((UUID)r.get("listener_id"));if(p.truth("SELECT live_pair_blocked(?,?)",who,r.get("listener_id")))throw denied(409,"LISTENER_UNAVAILABLE","This listener is unavailable for repeat booking.");return calendar.slots(who,(UUID)r.get("listener_id"),1,null);}
}
